head.script:
// https://inswave01.atlassian.net/browse/WAEA-1218
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
};



// 모든 버튼이 같은 기본 옵션으로 호출하고, 버튼마다 문자열 옵션 하나에만 앰퍼샌드가 들어간 값을 넣는다.
//  차트 설정은 모든 버튼이 동일하며 chart.title 만 인자로 받는다.
scwin.runCase = function (strChartTitle, objOverride, strShow, strFileName) {
    let options = {
        "fileName" : strFileName,
        "extension" : "xlsx",
        "sheetName" : "mysheet",
        "chart" : {
            "chartName" : "bar",
            "title" : strChartTitle,
            "startRowIndex" : 9,
            "startColIndex" : 6,
            "endRowIndex" : 30,
            "endColIndex" : 12,
            "catAxisRange" : { "startRowIndex" : 0, "startColIndex" : 1, "endRowIndex" : 0, "endColIndex" : 4 },
            "serAxisRange" : { "startRowIndex" : 1, "startColIndex" : 0, "endRowIndex" : 6, "endColIndex" : 4 },
            "dataAxisRange" : { "startRowIndex" : 1, "startColIndex" : 1, "endRowIndex" : 6, "endColIndex" : 4 }
        }
    };

    for (let sKey in objOverride) {
        options[sKey] = objOverride[sKey];
    }

    target1.advancedExcelDownload(options);

    scwin.setReturnValue(strShow);
    scwin.setReturnValue("");
};



// [A] 어떤 옵션에도 특수문자가 없다. (정상 동작 대조군)
scwin.btn_plain_onclick = function () {
    scwin.runCase("RnD 실적", {}, "[A] 특수문자 없음", "esc_plain");
};



// [B] chart.title 에만 앰퍼샌드를 넣는다.
scwin.btn_chartTitle_onclick = function () {
    scwin.runCase("R&D 실적", {}, "[B] chart.title = R&D 실적", "esc_chart_title");
};



// [C] sheetName 에만 앰퍼샌드를 넣는다.
scwin.btn_sheetName_onclick = function () {
    scwin.runCase("RnD 실적", { "sheetName" : "A&B" }, "[C] sheetName = A&B", "esc_sheet_name");
};



// [D] desc 에만 앰퍼샌드를 넣는다.
scwin.btn_desc_onclick = function () {
    scwin.runCase("RnD 실적", { "desc" : "A&B" }, "[D] desc = A&B", "esc_desc");
};



// [E] rowNumHeaderValue 에만 앰퍼샌드를 넣는다.
scwin.btn_rowNum_onclick = function () {
    scwin.runCase("RnD 실적", { "rowNumVisible" : "true", "rowNumHeaderValue" : "R&D" }, "[E] rowNumHeaderValue = R&D", "esc_rownum");
};



// [F] fileName 에만 앰퍼샌드를 넣는다. (같은 함수의 다른 문자열 옵션은 정상 동작한다는 대조군)
scwin.btn_fileName_onclick = function () {
    scwin.runCase("RnD 실적", {}, "[F] fileName = A&B", "A&B");
};
